"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["85151"],{47747(e){e.exports=JSON.parse('{"id":"FIN-1022","slug":"donor-advised-fund","term":"Donor-Advised Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A donor-advised fund is an account, mainly used in the United States, held by a sponsoring charity, into which a donor makes an irrevocable gift, receives an immediate tax deduction and later recommends grants to other charities over time.","explanation":["Donor-advised funds separate the timing of the tax deduction from the timing of giving to specific charities. The donor contributes cash, shares or other assets to the fund. The gift is generally deductible in that year, and the money can then be invested and grow tax-free. Over the following months or years, the donor recommends grants to charities of their choice.","For example, someone with an unusually high income in one year might contribute a large sum to a donor-advised fund to receive the deduction in that year, then spread the actual grants to charities over the next ten years.","Once contributed, the money legally belongs to the sponsoring charity, which has final say over grants, although it usually follows the donor\'s recommendations.","Donor-advised funds are popular because they are simple and cheaper to run than a private foundation. Critics note that money can sit in the funds for years before reaching working charities, and there have been proposals to require faster payouts."],"note":"","total":1500,"prev":{"slug":"dollarization","term":"Dollarization"},"next":{"slug":"double-entry-bookkeeping","term":"Double-Entry Bookkeeping"}}')}}]);